-- T07 · M0 gate: the §5b catalogue seed (DESIGN §5b; BUILD_PLAN §3 M0 exit).
-- Runs after `supabase db reset` (migrations + supabase/seed/*.sql, generated by
-- packages/fixtures). Asserts the seeded world, not the schema: phase counts,
-- Aurelia's 72 / 41 / 77 and its late filings, and the runtime switches the
-- fixture seed sets.
begin;
create extension if not exists pgtap with schema extensions;
select plan(21);

-- Phases ------------------------------------------------------------------------------
select is(
  (select array_agg(slug order by slug) from core.phases where status <> 'completed'),
  array[
    'aurelia-heights-phase-2', 'cedar-walk-phase-2', 'coral-towers', 'heron-point-phase-2',
    'juniper-enclave', 'kestrel-park', 'laurel-residency', 'sapphire-grove-phase-1'
  ]::text[],
  'the 8 seeded phases (the unit of a page, a score and a follow)'
);
select is(
  (select count(*)::int from core.phases ph
     join core.projects p on p.id = ph.project_id
     join core.developer_groups g on g.id = p.group_id
   where ph.status = 'completed' and g.slug = 'northfield-estates'),
  6,
  'plus Northfield''s 6 finished phases for the track record'
);
select is(
  (select count(*)::int from core.score_runs where status = 'published'),
  8,
  'one published score run per seeded phase'
);
select is(
  (select count(*)::int from core.developer_groups),
  7,
  '7 developer groups (6 with a page, plus Ashgrove invited on 16 Oct 2026)'
);

-- Aurelia Heights, Phase 2: 72 / 41 / 77 -----------------------------------------------
select is(
  (select rera_number from core.rera_registrations r
     join core.phases ph on ph.id = r.phase_id where ph.slug = 'aurelia-heights-phase-2'),
  'GGM/673/405/2022/117',
  'Aurelia''s RERA number'
);
select results_eq(
  $$select f.sold_pct::int, f.built_pct::int from core.qpr_filings f
      join core.rera_registrations r on r.id = f.registration_id
      join core.phases ph on ph.id = r.phase_id
    where ph.slug = 'aurelia-heights-phase-2' and f.quarter = '2026-Q2'$$,
  $$values (72, 41)$$,
  'Aurelia''s Apr–Jun 2026 QPR: 72% sold, 41% built'
);
select is(
  (select (f.value #>> '{}')::int from core.facts f
     join core.phases ph on ph.id = f.subject_id
   where f.subject_type = 'phase' and ph.slug = 'aurelia-heights-phase-2'
     and f.attribute = 'progress.time_used_pct' and f.superseded_by is null),
  77,
  'Aurelia has used 77% of the promised time today'
);
select is(
  (select count(*)::int from core.qpr_filings f
     join core.rera_registrations r on r.id = f.registration_id
     join core.phases ph on ph.id = r.phase_id
   where ph.slug = 'aurelia-heights-phase-2'),
  14,
  'Aurelia has a filing row for each of the 14 quarters since registration'
);
select is(
  (select count(*)::int from core.qpr_filings f
     join core.rera_registrations r on r.id = f.registration_id
     join core.phases ph on ph.id = r.phase_id
   where ph.slug = 'aurelia-heights-phase-2' and f.sold_pct is not null),
  8,
  'with progress values only for the 8 §5b quarters (no invented figures)'
);
select results_eq(
  $$select f.quarter, f.due_on, f.filed_on from core.qpr_filings f
      join core.rera_registrations r on r.id = f.registration_id
      join core.phases ph on ph.id = r.phase_id
    where ph.slug = 'aurelia-heights-phase-2' and f.status = 'late'
    order by f.quarter$$,
  $$values ('2024-Q3'::text, '2024-10-15'::date, '2024-10-27'::date),
           ('2025-Q1', '2025-04-15'::date, '2025-05-26'::date),
           ('2025-Q4', '2026-01-15'::date, '2026-02-22'::date)$$,
  'Aurelia''s late filings: Jul–Sep 2024, Jan–Mar 2025, Oct–Dec 2025'
);
select is(
  (select count(*)::int from core.qpr_filings f
     join core.rera_registrations r on r.id = f.registration_id
     join core.phases ph on ph.id = r.phase_id
   where ph.slug = 'aurelia-heights-phase-2' and f.status = 'late'
     and f.quarter between '2024-Q3' and '2026-Q2'),
  3,
  'QPRs filed late in 3 of the last 8 quarters'
);
select results_eq(
  $$select f.status, f.due_on, f.filed_on from core.qpr_filings f
      join core.rera_registrations r on r.id = f.registration_id
      join core.phases ph on ph.id = r.phase_id
    where ph.slug = 'aurelia-heights-phase-2' and f.quarter = '2026-Q3'$$,
  $$values ('missing'::text, '2026-10-15'::date, null::date)$$,
  'Aurelia''s Jul–Sep 2026 QPR is missing, due 15 Oct 2026'
);
select results_eq(
  $$select r.original_completion, r.original_completion_precision::text from core.rera_registrations r
      join core.phases ph on ph.id = r.phase_id where ph.slug = 'aurelia-heights-phase-2'$$,
  $$values ('2027-12-01'::date, 'month'::text)$$,
  'Aurelia''s original completion is Dec 2027 (month precision)'
);
select is(
  (select (value ->> 'count')::int from core.facts f
     join core.phases ph on ph.id = f.subject_id
   where f.subject_type = 'phase' and ph.slug = 'aurelia-heights-phase-2'
     and f.attribute = 'orders.complaints_against_promoter_24m' and f.superseded_by is null),
  14,
  '14 complaints decided against the promoter in 24 months'
);
select is(
  (select months from core.blanket_extensions where advisory_on = '2026-07-31'),
  4,
  'the MoHUA blanket extension of 31 Jul 2026 adds 4 months'
);

-- Laurel: the group's insolvency ----------------------------------------------------------
select results_eq(
  $$select e.kind, e.event_on from core.insolvency_events e
      join core.developers d on d.id = e.developer_id
      join core.developer_groups g on g.id = d.group_id
    where g.slug = 'elmstone-developers'$$,
  $$values ('admitted'::text, '2023-03-12'::date)$$,
  'an Elmstone group company was admitted to CIRP on 12 Mar 2023'
);

-- Runtime switches the fixture seed sets -------------------------------------------------
select ok(
  exists (
    select 1 from ops.audit_log
    where entity = 'ops.runtime_settings' and entity_id = 'env' and after ->> 'value' = 'fixture'
  ),
  'the seed upserted ops.runtime_settings(env) = fixture (audited)'
);
select ok(ops.env() in ('fixture', 'test'), 'so the database runs a frozen-clock environment');
select is(ops.now(), '2026-10-18 12:00:00+05:30'::timestamptz, 'and ops.now() is 18 Oct 2026, 12:00 IST');
select ok((select enabled from ops.feature_flags where key = 'bands_public'), 'bands_public is on in the fixture world');
select is(
  (select array_agg(key order by key) from ops.feature_flags
   where key in ('ai_ask', 'ai_doc_check', 'ai_staging') and not enabled),
  array['ai_ask', 'ai_doc_check', 'ai_staging']::text[],
  'the 3 AI kill switches are off until M5'
);

select * from finish();
rollback;
